deps = {"orders": ["customers", "products"], "reviews": ["products", "customers"],
        "products": [], "customers": []}
order, temp = [], set()
def visit(n, stack):
    if n in temp: raise ValueError("cycle at " + n)
    if n not in order:
        temp.add(n)
        for d in deps[n]: visit(d, stack)
        temp.remove(n); order.append(n)
for n in deps: visit(n, [])
print("safe build order:", order)

